/**
 * Pre-generated seamless Voronoi texture for caustics.
 *
 * Generated by scripts/generateVoronoi.mjs — do not edit manually.
 * 512×512 pixels, 8×8 cells, RGB PNG.
 *
 * Channels:
 *   R = F1 (distance to nearest cell point — bright between cells)
 *   G = 1−(F2−F1) (inverted edge distance — bright at ridges/boundaries)
 *   B = unused
 */
import * as THREE from "three/webgpu";

// prettier-ignore
const PNG_DATA_URL = "data:image/png;base64,";

/**
 * Creates a tileable Voronoi texture from the embedded PNG.
 * The texture loads asynchronously from the data URL but is typically
 * ready before the first render frame.
 */
export function createVoronoiTexture(): THREE.Texture {
  const tex = new THREE.TextureLoader().load(PNG_DATA_URL);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  return tex;
}
